def copiar_logs_antiguos(apps, schema_editor):
    """Conserva los análisis de logs creados con el modelo anterior (LogAnalysis)."""
    import json

    LogAnalysis = apps.get_model('scanner', 'LogAnalysis')
    Analisis = apps.get_model('scanner', 'Analisis')
    for viejo in LogAnalysis.objects.all():
        try:
            resultado = json.loads(viejo.resultado or '{}')
        except ValueError:
            resultado = {}
        if not isinstance(resultado, dict):
            resultado = {}
        nuevo = Analisis.objects.create(
            tipo='logs',
            objetivo=viejo.archivo_nombre[:255],
            nivel_riesgo=str(resultado.get('resumen', {}).get('nivel_riesgo', ''))[:10],
            resultado=resultado,
        )
        # auto_now_add pisa la fecha al crear: se restaura la original.
        Analisis.objects.filter(pk=nuevo.pk).update(fecha=viejo.fecha_analisis)


